// Frontend translation engine. Reads the same desktop/langs/*.json the Go
// side serves (dotted keys, $meta, CLDR plural objects) and implements the
// same three rules internal/i18n does, so a sentence renders identically on
// either side of the bridge.
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
// @ts-ignore wailsjs bindings are generated by wails build
import { GetLanguage, SetLanguage } from "../../wailsjs/go/controllers/System";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";

export type LocaleMeta = {
  code: string;
  name: string;
  nativeName: string;
  autoTranslated: boolean;
};

export type Vars = Record<string, string | number>;
export type Catalogue = Record<string, unknown>;

export const FALLBACK = "en";

// Every langs/*.json, pulled in at build time. The glob reaches outside the
// Vite root into desktop/langs; vite.config.ts allows that.
const files = import.meta.glob("../../../langs/*.json", { eager: true }) as Record<
  string,
  { default: Catalogue }
>;

export const catalogues: Record<string, Catalogue> = Object.fromEntries(
  Object.entries(files).map(([file, mod]) => [
    file.split("/").pop()!.replace(/\.json$/, ""),
    mod.default,
  ]),
);

const PLURAL_KEYS = new Set(["zero", "one", "two", "few", "many", "other"]);

// A node whose keys are all plural categories is one translatable unit, not
// a namespace to keep walking into.
function isPluralUnit(node: unknown): node is Record<string, string> {
  if (typeof node !== "object" || node === null || Array.isArray(node)) return false;
  const keys = Object.keys(node);
  return keys.length > 0 && keys.every((k) => PLURAL_KEYS.has(k));
}

function readPath(catalogue: Catalogue | undefined, key: string): unknown {
  if (!catalogue) return undefined;
  let node: unknown = catalogue;
  for (const part of key.split(".")) {
    if (typeof node !== "object" || node === null) return undefined;
    node = (node as Record<string, unknown>)[part];
    if (node === undefined) return undefined;
  }
  return node;
}

function pickPluralForm(node: Record<string, string>, lang: string, vars?: Vars): string {
  let category = "other";
  const count = vars?.count;
  if (typeof count === "number") {
    category = new Intl.PluralRules(lang).select(count);
  }
  // A translator may skip a category; "other" is mandatory and beats nothing.
  return node[category] ?? node.other ?? "";
}

function interpolate(text: string, lang: string, vars?: Vars): string {
  if (!vars || !text.includes("{{")) return text;
  return text.replace(/\{\{(\w+)\}\}/g, (token, name: string) => {
    const value = vars[name];
    if (value === undefined) return token;
    // A count is prose and takes the locale's separators; anything else —
    // ports, versions, PIDs — must be inserted exactly as given.
    if (name === "count" && typeof value === "number") {
      return new Intl.NumberFormat(lang).format(value);
    }
    return String(value);
  });
}

// The pure renderer: no React, no bindings, unit-testable on its own.
export function translate(
  all: Record<string, Catalogue>,
  lang: string,
  key: string,
  vars?: Vars,
): string {
  let node = readPath(all[lang], key);
  let resolved = lang;
  if (node === undefined) {
    node = readPath(all[FALLBACK], key);
    resolved = FALLBACK;
    if (node === undefined) return key;
  }
  if (typeof node === "string") return interpolate(node, resolved, vars);
  if (isPluralUnit(node)) return interpolate(pickPluralForm(node, resolved, vars), resolved, vars);
  return key;
}

// Locale listing for selectors: fallback first, the rest alphabetical.
export function localesOf(all: Record<string, Catalogue>): LocaleMeta[] {
  return Object.entries(all)
    .map(([code, catalogue]) => {
      const meta = (catalogue.$meta ?? {}) as Partial<LocaleMeta>;
      return {
        code,
        name: meta.name ?? code,
        nativeName: meta.nativeName ?? code,
        autoTranslated: meta.autoTranslated === true,
      };
    })
    .sort((a, b) =>
      a.code === FALLBACK ? -1 : b.code === FALLBACK ? 1 : a.code.localeCompare(b.code),
    );
}

type I18n = {
  lang: string;
  locales: LocaleMeta[];
  setLang: (code: string) => Promise<void>;
  t: (key: string, vars?: Vars) => string;
};

const I18nContext = createContext<I18n | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLang] = useState(FALLBACK);

  useEffect(() => {
    GetLanguage()
      .then((code: string) => code && setLang(code))
      .catch(() => {
        /* not inside a live Wails window yet: stay on the fallback */
      });
    // SetLanguage emits this locally; other processes emit it through their
    // configuration-file watcher, which reaches us here as well.
    return EventsOn("language:changed", (code: string) => setLang(code));
  }, []);

  const setLangPersisted = useCallback(async (code: string) => {
    setLang(code);
    await SetLanguage(code);
  }, []);

  const value = useMemo<I18n>(
    () => ({
      lang,
      locales: localesOf(catalogues),
      setLang: setLangPersisted,
      t: (key, vars) => translate(catalogues, lang, key, vars),
    }),
    [lang, setLangPersisted],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18n {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n needs an I18nProvider above it");
  return ctx;
}

export function useT() {
  return useI18n().t;
}
